using System.Text.Json;
using Indra.Ocr.Pdf;
using Indra.Ocr.Document;

namespace Indra.Ocr.Tests;

/// <summary>
/// Step 140: the PDFium surface (<see cref="PdfDocument"/> / <see cref="PdfPage"/>) against
/// <c>fixtures/pdf.json</c>, generated by <c>tools/scripts/test/gen_pdf_fixtures.py</c> from
/// the Python reference (pypdfium2 5.14.0, which bundles the same PDFium build as the
/// PDFiumCore 156.0.8076 package).
/// </summary>
/// <remarks>
/// The sample PDFs travel base64-encoded inside the fixture, so the tests need no Python and
/// no binary in git. Everything is compared bit-exactly: the renders byte for byte, the page
/// sizes and character boxes as raw doubles, the affine as PDFium's own integer output.
/// </remarks>
public class PdfTests
{
    private static readonly JsonElement Fx = Fixtures.Load("pdf.json");

    private static IEnumerable<(string Name, JsonElement Doc)> Documents()
    {
        foreach (var d in Fx.GetProperty("documents").EnumerateArray())
        {
            yield return (d.GetProperty("name").GetString()!, d);
        }
    }

    private static JsonElement Document(string name) =>
        Documents().Single(d => d.Name == name).Doc;

    private static byte[] Bytes(JsonElement doc) => B64.Bytes(doc.GetProperty("pdf").GetString()!);

    private static string? Password(JsonElement doc) =>
        doc.GetProperty("password").ValueKind == JsonValueKind.Null
            ? null
            : doc.GetProperty("password").GetString();

    private static PdfDocument Open(JsonElement doc) => PdfDocument.Open(Bytes(doc), Password(doc));

    /// <summary>Exact equality, but signed zero must match too (0.0 vs -0.0 swaps bits).</summary>
    private static void Same(double expected, double actual)
    {
        Assert.True(expected.Equals(actual) &&
                    (expected != 0 || BitConverter.DoubleToInt64Bits(expected) ==
                                      BitConverter.DoubleToInt64Bits(actual)),
                    $"expected {expected:R}, got {actual:R}");
    }

    private static IEnumerable<(JsonElement Page, ITextPage Loaded)> Pages(JsonElement doc)
    {
        using PdfDocument pdf = Open(doc);
        int i = 0;
        foreach (var page in doc.GetProperty("pages").EnumerateArray())
        {
            yield return (page, pdf.LoadPage(i++));
        }
    }

    [Fact]
    public void Page_counts_and_sizes_match_pypdfium2()
    {
        int seen = 0;
        foreach (var (name, doc) in Documents())
        {
            using PdfDocument pdf = Open(doc);
            var pages = doc.GetProperty("pages");
            Assert.True(pages.GetArrayLength() == pdf.PageCount,
                        $"{name}: {pdf.PageCount} pages, expected {pages.GetArrayLength()}");

            int i = 0;
            foreach (var p in pages.EnumerateArray())
            {
                var size = Fixtures.DoubleArray(p.GetProperty("size"));
                var (w, h) = pdf.PageSize(i);
                Same(size[0], w);
                Same(size[1], h);
                using ITextPage page = pdf.LoadPage(i);
                Same(size[0], page.Width);
                Same(size[1], page.Height);
                i++;
            }

            seen++;
        }

        Assert.Equal(Fx.GetProperty("documents").GetArrayLength(), seen);
    }

    [Fact]
    public void Renders_match_pypdfium2()
    {
        foreach (var (name, doc) in Documents())
        {
            foreach (var (pageJson, page) in Pages(doc))
            {
                using (page)
                {
                    foreach (var r in pageJson.GetProperty("renders").EnumerateArray())
                    {
                        double scale = r.GetProperty("scale").GetDouble();
                        var got = page.Render(scale);
                        Assert.Equal(r.GetProperty("width").GetInt32(), got.Width);
                        Assert.Equal(r.GetProperty("height").GetInt32(), got.Height);
                        Assert.Equal(got.Width * got.Height, got.Pixels.Length);

                        var want = B64.ZBytes(r.GetProperty("gray").GetString()!);
                        Assert.True(want.AsSpan().SequenceEqual(got.Pixels),
                                    $"{name} at scale {scale}: rendered pixels differ");
                    }
                }
            }
        }
    }

    [Fact]
    public void Chars_match_pypdfium2()
    {
        foreach (var (name, doc) in Documents())
        {
            foreach (var (pageJson, page) in Pages(doc))
            {
                using (page)
                {
                    var chars = page.ReadChars();
                    var items = pageJson.GetProperty("chars");
                    Assert.True(items.GetArrayLength() == chars.Count,
                                $"{name}: {chars.Count} chars, expected {items.GetArrayLength()}");

                    int i = 0;
                    foreach (var e in items.EnumerateArray())
                    {
                        var c = chars[i++];
                        Assert.Equal(e.GetProperty("code").GetInt64(), (long)c.Code);
                        Assert.Equal(e.GetProperty("angle").GetSingle(), c.Angle);
                        Assert.Equal(e.GetProperty("has_box").GetBoolean(), c.HasBox);
                        var box = Fixtures.DoubleArray(e.GetProperty("box"));
                        Same(box[0], c.Left);
                        Same(box[1], c.Right);
                        Same(box[2], c.Bottom);
                        Same(box[3], c.Top);
                    }
                }
            }
        }
    }

    [Fact]
    public void Device_affine_matches_pypdfium2()
    {
        foreach (var (name, doc) in Documents())
        {
            foreach (var (pageJson, page) in Pages(doc))
            {
                using (page)
                {
                    double[,] affine = page.DeviceAffine();
                    int row = 0;
                    foreach (var e in pageJson.GetProperty("affine").EnumerateArray())
                    {
                        var want = Fixtures.DoubleArray(e);
                        for (int j = 0; j < 3; j++)
                        {
                            Same(want[j], affine[row, j]);
                        }

                        row++;
                    }

                    Assert.True(row == 2, $"{name}: the affine must be a [2, 3] matrix");
                }
            }
        }
    }

    [Fact]
    public void Invisible_text_fraction_matches_pypdfium2()
    {
        foreach (var (name, doc) in Documents())
        {
            foreach (var (pageJson, page) in Pages(doc))
            {
                using (page)
                {
                    Same(pageJson.GetProperty("invisible_frac").GetDouble(),
                         page.InvisibleTextFraction());
                }
            }
        }
    }

    /// <summary>
    /// A document that cannot be opened fails with pypdfium2's message, because
    /// <c>document.Converter</c> puts it in the "cannot open the PDF (...)" output and
    /// looks for "password" in it to tell a locked file from a broken one.
    /// </summary>
    [Fact]
    public void Unopenable_documents_match_pypdfium2()
    {
        int cases = 0;
        foreach (var e in Fx.GetProperty("errors").EnumerateArray())
        {
            string name = e.GetProperty("name").GetString()!;
            var data = B64.Bytes(e.GetProperty("pdf").GetString()!);
            string? password = e.GetProperty("password").ValueKind == JsonValueKind.Null
                ? null
                : e.GetProperty("password").GetString();
            var message = e.GetProperty("message");

            if (message.ValueKind == JsonValueKind.Null)
            {
                using var ok = PdfDocument.Open(data, password);
                Assert.True(ok.PageCount > 0, $"{name}: expected the document to open");
            }
            else
            {
                var err = Assert.Throws<TextPageError>(() => PdfDocument.Open(data, password));
                Assert.Equal(message.GetString(), err.Message);
            }

            cases++;
        }

        Assert.Equal(5, cases);
    }

    [Fact]
    public void Open_from_path_reads_the_same_bytes()
    {
        var doc = Document("text");
        string path = Path.Combine(Path.GetTempPath(), $"indra-ocr-pdf-{Guid.NewGuid():N}.pdf");
        try
        {
            File.WriteAllBytes(path, Bytes(doc));
            using var pdf = PdfDocument.Open(path);
            Assert.Equal(doc.GetProperty("pages").GetArrayLength(), pdf.PageCount);
            using ITextPage page = pdf.LoadPage(0);
            var size = Fixtures.DoubleArray(doc.GetProperty("pages")[0].GetProperty("size"));
            Same(size[0], page.Width);
            Same(size[1], page.Height);
        }
        finally
        {
            File.Delete(path);
        }
    }

    [Fact]
    public void Disposed_document_and_page_throw()
    {
        var doc = Document("empty");
        var pdf = Open(doc);
        var page = pdf.LoadPage(0);
        page.Dispose();
        Assert.Throws<ObjectDisposedException>(() => page.ReadChars());
        pdf.Dispose();
        Assert.Throws<ObjectDisposedException>(() => pdf.LoadPage(0));
    }
}
